const FILES = ["./", "index.html", "images/login/login-1-site-walk.webp", "images/login/login-2-crane-scaffold.webp", "images/login/login-3-ppe.webp", "images/login/login-4-services.webp", "images/login/login-5-protection.webp", "images/q/diag-q11.webp", "images/q/diag-q14.webp", "images/q/diag-q3.webp", "images/q/diag-q7.webp", "images/q/t1-q25.webp", "images/q/t1-q34.webp", "images/q/t11-q47.webp", "images/q/t12-q14.webp", "images/q/t13-q26.webp", "images/q/t13-q8.webp", "images/q/t14-q26.webp", "images/q/t14-q8.webp", "images/q/t15-q47.webp", "images/q/t15-q8.webp", "images/q/t16-q38.webp", "images/q/t16-q8.webp", "images/q/t17-q47.webp", "images/q/t18-q38.webp", "images/q/t18-q8.webp", "images/q/t19-q26.webp", "images/q/t19-q47.webp", "images/q/t2-q27.webp", "images/q/t2-q37.webp", "images/q/t20-q14.webp", "images/q/t20-q38.webp", "images/q/t3-q18.webp", "images/q/t3-q35.webp", "images/q/t3-q47.webp", "images/q/t4-q26.webp", "images/q/t5-q47.webp", "images/q/t8-q14.webp", "images/q/t8-q38.webp", "images/q/t9-q26.webp", "images/q/t9-q35.webp"];
self.addEventListener("install", e => { e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting())); });
self.addEventListener("activate", e => { e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim())); });
self.addEventListener("fetch", e => {
  if(e.request.method !== "GET") return;
  e.respondWith(caches.match(e.request, {ignoreSearch: true}).then(hit => hit || fetch(e.request).then(res => {
    if(res.ok && new URL(e.request.url).origin === location.origin){ const copy = res.clone(); caches.open(CACHE).then(c => c.put(e.request, copy)); }
    return res;
  }).catch(() => caches.match("index.html"))));
});
